import { defineCollection } from "astro:content";
import { glob } from "astro/loaders";
import { z } from "astro/zod";

/**
 * Generated by scripts/fetch-daily-terms.ts from the daily-term-SE-Growth
 * archive. Never edit src/content/daily-terms/ by hand; edit the archive and
 * re-run `bun run fetch:terms` instead.
 */
const dailyTerms = defineCollection({
  loader: glob({ pattern: "**/*.md", base: "./src/content/daily-terms" }),
  schema: z.object({
    title: z.string(),
    termSlug: z.string(),
    year: z.number().int(),
    month: z.number().int().min(1).max(12),
    monthName: z.string(),
    day: z.number().int().nullable(),
    order: z.number().int(),
    source: z.string(),
    sourceUrl: z.url(),
    excerpt: z.string(),
  }),
});

export const collections = { dailyTerms };
